	cmd.SetOut(io.Discard)
	cmd.SetErr(io.Discard)
	err := runResume(context.Background(), cmd, "nonexistent", false)
	if err == nil {
		t.Error("runResume() expected error for nonexistent branch, got nil")
	}
}

