package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "cursor-cli" {
		return
	}
	Register(&CursorCLI{})
}

// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
// The CLI binary is called "agent" and uses Cursor's hooks system via
// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
//
// All E2E interactions use interactive (tmux) mode so that the full hook
// lifecycle fires (sessionStart, beforeSubmitPrompt, stop, sessionEnd).
// Headless (-p) mode skips beforeSubmitPrompt and stop hooks.
type CursorCLI struct{}

func (a *CursorCLI) Name() string               { return "cursor-cli" }
func (a *CursorCLI) Binary() string             { return "agent" }
func (a *CursorCLI) EntireAgent() string        { return "cursor" }
func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }

// PromptPattern returns a regex matching Cursor's ready-state prompt markers.
// Cursor has used multiple startup/completion markers across releases.
func (a *CursorCLI) PromptPattern() string {
	return `(/ commands|Plan, search, build anything|Add a follow-up)`
}

func (a *CursorCLI) IsTransientError(out Output, err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	combined := out.Stdout + out.Stderr
	for _, p := range []string{
		"overloaded",
		"rate limit",
		"429",
		"503",
		"529",
		"ECONNRESET",
		"ETIMEDOUT",
		"server error",
		"Internal Server Error",
	} {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

func (a *CursorCLI) Bootstrap() error {
	// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
	// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
	if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
		return errors.New("CURSOR_API_KEY must be set on CI for cursor-cli E2E tests")
	}
	return nil
}

// cursorConfigDir creates an isolated per-session config directory for the
// Cursor CLI. Each session gets its own XDG_CONFIG_HOME so that parallel tests
// don't race on the shared ~/.config/cursor/cli-config.json file.
// The directory is pre-seeded with an empty cli-config.json to avoid the
// atomic temp-file rename that triggers the ENOENT race.
func cursorConfigDir() (string, error) {
	tmp, err := os.MkdirTemp("", "cursor-e2e-config-*")
	if err != nil {
		return "", fmt.Errorf("create temp config dir: %w", err)
	}
	cursorDir := filepath.Join(tmp, "cursor")
	if err := os.MkdirAll(cursorDir, 0o755); err != nil {
		return "", fmt.Errorf("mkdir cursor config: %w", err)
	}
	if err := os.WriteFile(filepath.Join(cursorDir, "cli-config.json"), []byte("{}"), 0o644); err != nil {
		return "", fmt.Errorf("seed cli-config.json: %w", err)
	}
	return tmp, nil
}

func (a *CursorCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	timeout := 90 * time.Second
	if cfg.PromptTimeout > 0 {
		timeout = cfg.PromptTimeout
	}

	displayCmd := a.Binary() + " --force --workspace " + dir + " (interactive prompt: " + prompt + ")"

	// Start an interactive tmux session so all hooks fire
	// (beforeSubmitPrompt and stop don't fire in headless -p mode).
	s, err := a.startInteractiveSession(dir)
	if err != nil {
		return Output{Command: displayCmd, ExitCode: -1},
			fmt.Errorf("start interactive session: %w", err)
	}
	defer s.Close()

	// Wait for trust dialog and accept it.
	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1}, err
	}

	// Wait for the TUI to be ready.
	if _, err := s.WaitFor(a.PromptPattern(), 45*time.Second); err != nil {
		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
			fmt.Errorf("waiting for startup prompt: %w", err)
	}

	// Send the prompt.
	if err := s.Send(prompt); err != nil {
		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
			fmt.Errorf("sending prompt: %w", err)
	}

	// Wait for the "Add a follow-up" completion marker that appears after the
	// agent finishes processing. We cannot reuse PromptPattern() here because
	// it matches ready-state UI markers that can already be visible while the
	// model is still thinking, causing WaitFor to settle prematurely.
	content, waitErr := s.WaitFor(`Add a follow-up`, timeout)
	if waitErr != nil {
		// Check for deadline exceeded to allow transient error detection.
		if ctx.Err() == context.DeadlineExceeded {
			waitErr = fmt.Errorf("%w: %w", waitErr, context.DeadlineExceeded)
		}
		return Output{Command: displayCmd, Stdout: content, ExitCode: -1}, waitErr
	}

	return Output{Command: displayCmd, Stdout: content, ExitCode: 0}, nil
}

func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
	s, err := a.startInteractiveSession(dir)
	if err != nil {
		return nil, err
	}

	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
		_ = s.Close()
		return nil, err
	}

	// Wait for the TUI to be ready (input prompt).
	if _, err := s.WaitFor(a.PromptPattern(), 45*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
	}
	s.stableAtSend = ""

	return s, nil
}

// startInteractiveSession creates a new tmux session running the Cursor CLI
// in interactive mode (no -p flag) so all hooks fire.
func (a *CursorCLI) startInteractiveSession(dir string) (*TmuxSession, error) {
	// Resolve to absolute path so tmux can find the binary even if its
	// shell doesn't inherit the test process's PATH (common on CI).
	bin, err := exec.LookPath(a.Binary())
	if err != nil {
		return nil, fmt.Errorf("agent binary not found: %w", err)
	}

	// Create an isolated config directory for this session so parallel tests
	// don't race on the shared ~/.config/cursor/cli-config.json file.
	configDir, err := cursorConfigDir()
	if err != nil {
		return nil, fmt.Errorf("create cursor config dir: %w", err)
	}

	// Build env-wrapped command so the tmux session inherits critical env vars.
	// tmux starts a new shell that doesn't inherit Go's os.Environ().
	var envArgs []string
	for _, key := range []string{"CURSOR_API_KEY", "PATH", "HOME", "TERM"} {
		if v := os.Getenv(key); v != "" {
			envArgs = append(envArgs, key+"="+v)
		}
	}
	// Point XDG_CONFIG_HOME to our isolated dir so cursor writes its config
	// there instead of ~/.config/cursor/. We keep the real HOME so that
	// auth credentials (keychain, OAuth tokens) remain accessible.
	envArgs = append(envArgs, "XDG_CONFIG_HOME="+configDir)

	args := append([]string{"env"}, envArgs...)
	args = append(args, bin, "--force", "--workspace", dir)

	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
	unset := []string{"CI"}
	s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
	if err != nil {
		_ = os.RemoveAll(configDir)
		return nil, err
	}
	s.OnClose(func() { _ = os.RemoveAll(configDir) })
	return s, nil
}

// acceptTrustDialogIfNeeded checks whether the workspace trust dialog appears
// and presses "a" to accept it. The dialog only shows on the first launch in
// a workspace — subsequent sessions in the same directory skip it.
func (a *CursorCLI) acceptTrustDialogIfNeeded(s *TmuxSession) error {
	// Race: either the trust dialog or the input prompt will appear first.
	// Use a short timeout to check for the trust dialog without blocking
	// too long if the workspace is already trusted.
	content, err := s.WaitFor(`Trust this workspace|`+a.PromptPattern(), 45*time.Second)
	if err != nil {
		return fmt.Errorf("waiting for trust dialog or prompt: %w", err)
	}
	if strings.Contains(content, "Trust this workspace") {
		if err := s.SendKeys("a"); err != nil {
			return fmt.Errorf("accepting trust dialog: %w", err)
		}
	}
	return nil
}

//go:build e2e

package tests

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/e2e/entire"
	"github.com/entireio/cli/e2e/testutil"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestResumeFromFeatureBranch: agent creates a file on a feature branch and
// user commits, then switches back to main and runs `entire resume feature`.
// Verifies the branch is switched and the session is restored.
func TestResumeFromFeatureBranch(t *testing.T) {
	testutil.ForEachAgent(t, 3*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		mainBranch := testutil.GitOutput(t, s.Dir, "branch", "--show-current")

		// Commit files from `entire enable` so main has a clean working tree
		// for branch switching (mirrors a real repo where .gitignore is tracked).
		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Enable entire")

		// Do agent work on a feature branch.
		s.Git(t, "checkout", "-b", "feature")

		_, err := s.RunPrompt(t, ctx,
			"create a file at docs/hello.md with a paragraph about greetings. Do not ask for confirmation or approval, just make the change.")
		if err != nil {
			t.Fatalf("agent failed: %v", err)
		}

		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Add hello doc")
		testutil.WaitForCheckpoint(t, s, 30*time.Second)

		// Switch back to main and resume the feature branch.
		s.Git(t, "checkout", mainBranch)

		out, err := entire.Resume(s.Dir, "feature")
		require.NoError(t, err, "entire resume failed: %s", out)

		current := testutil.GitOutput(t, s.Dir, "branch", "--show-current")
		assert.Equal(t, "feature", current, "should be on feature branch after resume")
		assert.Contains(t, out, "To continue", "resume output should show resume instructions")
	})
}

// TestResumeSquashMergeMultipleCheckpoints: two agent prompts on a feature
// branch each get their own commit and checkpoint. The feature branch is
// squash-merged to main and `entire resume` should restore only the latest
// checkpoint (by CreatedAt), skipping older ones. Tests both squash merge message formats:
//
//   - GitHub format: trailers appear at the top level in the commit body
//     (e.g. "* Add red doc\n\nEntire-Checkpoint: aaa\n\n* Add blue doc\n\nEntire-Checkpoint: bbb")
//   - git CLI format: `git merge --squash` nests original commit messages
//     (including trailers) indented with 4 spaces inside the squash message
//
// Both formats are tested in a single function to share the expensive agent
// prompts. Main is reset between format tests.
func TestResumeSquashMergeMultipleCheckpoints(t *testing.T) {
	testutil.ForEachAgent(t, 5*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		mainBranch := testutil.GitOutput(t, s.Dir, "branch", "--show-current")

		// Commit files from `entire enable` so main has a clean working tree
		// for branch switching and squash merging.
		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Enable entire")

		// Create feature branch with two agent-assisted commits.
		s.Git(t, "checkout", "-b", "feature")

		_, err := s.RunPrompt(t, ctx,
			"create a file at docs/red.md with a paragraph about the colour red. Do not ask for confirmation or approval, just make the change.")
		if err != nil {
			t.Fatalf("prompt 1 failed: %v", err)
		}

		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Add red doc")
		testutil.WaitForCheckpoint(t, s, 30*time.Second)
		cp1Ref := testutil.GitOutput(t, s.Dir, "rev-parse", "entire/checkpoints/v1")

		_, err = s.RunPrompt(t, ctx,
			"create a file at docs/blue.md with a paragraph about the colour blue. Do not ask for confirmation or approval, just make the change.")
		if err != nil {
			t.Fatalf("prompt 2 failed: %v", err)
		}

		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Add blue doc")
		testutil.WaitForCheckpointAdvanceFrom(t, s.Dir, cp1Ref, 30*time.Second)

		// Record checkpoint IDs from both feature branch commits.
		cpID1 := testutil.GetCheckpointTrailer(t, s.Dir, "HEAD~1")
		cpID2 := testutil.GetCheckpointTrailer(t, s.Dir, "HEAD")
		require.NotEmpty(t, cpID1, "first commit should have checkpoint trailer")
		require.NotEmpty(t, cpID2, "second commit should have checkpoint trailer")
		require.NotEqual(t, cpID1, cpID2, "checkpoint IDs should be distinct")

		// Save main HEAD so we can reset between format tests.
		s.Git(t, "checkout", mainBranch)
		mainHead := testutil.GitOutput(t, s.Dir, "rev-parse", "HEAD")

		// --- Format 1: GitHub squash merge ---
		// GitHub puts each original commit message (including trailers) as
		// top-level bullet points in the squash commit body.
		s.Git(t, "merge", "--squash", "feature")
		githubMsg := fmt.Sprintf(
			"Squash merge feature (#1)\n\n* Add red doc\n\nEntire-Checkpoint: %s\n\n* Add blue doc\n\nEntire-Checkpoint: %s",
			cpID1, cpID2,
		)
		s.Git(t, "commit", "-m", githubMsg)

		out, err := entire.Resume(s.Dir, mainBranch)
		require.NoError(t, err, "github format: entire resume …40 chars truncated…ut, "older checkpoints skipped",
			"github format: squash merge should skip older checkpoints")

		// Reset main to before the squash merge for the next format test.
		s.Git(t, "reset", "--hard", mainHead)

		// --- Format 2: git merge --squash ---
		// The git CLI nests original commit messages (with trailers) indented
		// by 4 spaces inside "Squashed commit of the following:".
		s.Git(t, "merge", "--squash", "feature")

		// Sanity-check: the auto-generated SQUASH_MSG should contain both trailers.
		squashMsgBytes, err := os.ReadFile(filepath.Join(s.Dir, ".git", "SQUASH_MSG"))
		require.NoError(t, err, "read .git/SQUASH_MSG")
		squashMsgStr := string(squashMsgBytes)
		require.Contains(t, squashMsgStr, cpID1,
			"git SQUASH_MSG should contain first checkpoint ID")
		require.Contains(t, squashMsgStr, cpID2,
			"git SQUASH_MSG should contain second checkpoint ID")

		// Commit using the git-generated squash message directly (not via -m).
		// GIT_EDITOR=true prevents git from opening an editor while letting
		// it use .git/SQUASH_MSG natively with all hooks running.
		commitCmd := exec.Command("git", "commit")
		commitCmd.Dir = s.Dir
		commitCmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0", "GIT_EDITOR=true")
		commitOut, commitErr := commitCmd.CombinedOutput()
		fmt.Fprintf(s.ConsoleLog, "> git commit (GIT_EDITOR=true)\n%s\n", commitOut)
		require.NoError(t, commitErr, "git commit with squash message failed: %s", commitOut)

		out, err = entire.Resume(s.Dir, mainBranch)
		require.NoError(t, err, "git-cli format: entire resume failed: %s", out)
		assert.Contains(t, out, "older checkpoints skipped",
			"git-cli format: squash merge should skip older checkpoints")
	})
}

// TestResumeNoCheckpointOnBranch: resume on a feature branch that has only
// human commits (no agent interaction). Should switch to the branch and exit
// cleanly with an informational message, not an error.
func TestResumeNoCheckpointOnBranch(t *testing.T) {
	testutil.ForEachAgent(t, 1*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		mainBranch := testutil.GitOutput(t, s.Dir, "branch", "--show-current")

		// Commit files from `entire enable` so main has a clean working tree.
		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Enable entire")

		// Create a feature branch with only human commits.
		s.Git(t, "checkout", "-b", "no-checkpoint")
		require.NoError(t, os.MkdirAll(filepath.Join(s.Dir, "docs"), 0o755))
		require.NoError(t, os.WriteFile(
			filepath.Join(s.Dir, "docs", "human.md"),
			[]byte("# Written by a human\n"), 0o644,
		))
		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Human-only commit")

		// Switch back to main and try to resume the feature branch.
